import{_ as h,C as r,o as i,c as n,j as e,a as d,E as o,a5 as c}from"./chunks/framework.Dep_XxFZ.js";const P=JSON.parse('{"title":"会话线程","description":"","frontmatter":{},"headers":[],"relativePath":"components/thread.md","filePath":"components/thread.md","lastUpdated":1787173379000}'),s={name:"components/thread.md"},b={id:"会话线程",tabindex:"-1"};function u(p,t,x,m,g,q){const l=r("Badge"),a=r("XhDemo");return i(),n("div",null,[e("h1",b,[t[0]||(t[0]=d("会话线程 ",-1)),o(l,{type:"info",text:"thread"}),t[1]||(t[1]=d()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#会话线程","aria-label":'Permalink to "会话线程 <Badge type="info" text="thread" />"'},"​",-1))]),t[3]||(t[3]=c('<p>对话消息的滚动容器：新消息来了自动跟到底部，用户往上翻时停住。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>AI 对话、聊天记录的消息区。</li><li>消息是流式追加的，需要粘底行为。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>是普通的长列表：用<a href="./scroll-area">滚动区域</a>加<a href="./virtualizer">虚拟滚动</a>。</li><li>内容不会追加。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>三层必备：<code>root</code> · <code>viewport</code> · <code>content</code>。</li><li><code>threshold</code> 决定离底多近还算&quot;粘着&quot;；用户往上翻即脱离，回到底部自动恢复。</li><li><code>status</code> 驱动读屏播报（<code>live-region</code>）：流式生成时不能每个字都播报。</li><li>内置&quot;回到底部&quot;入口，也可以自己画。</li><li>支持向上加载更早的消息，加载后保持视觉位置不跳。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>root 的高度由外部给定，滚动才发生在 viewport 里面；root / viewport / content 三层缺一不可</p>',10)),o(a,{src:"thread/01-basic"}),t[4]||(t[4]=e("h3",{id:"粘底与回到底部",tabindex:"-1"},[d("粘底与回到底部 "),e("a",{class:"header-anchor",href:"#粘底与回到底部","aria-label":'Permalink to "粘底与回到底部"'},"​")],-1)),t[5]||(t[5]=e("p",null,"内容长高时自动跟到底；往上滚一下当场撒手，回到底部按钮随即露出，滚回阈值内又自动粘上",-1)),o(a,{src:"thread/02-stick"}),t[6]||(t[6]=e("h3",{id:"运行态与播报",tabindex:"-1"},[d("运行态与播报 "),e("a",{class:"header-anchor",href:"#运行态与播报","aria-label":'Permalink to "运行态与播报"'},"​")],-1)),t[7]||(t[7]=e("p",null,'status 由宿主持有，组件只把它透出成 data-status；viewport 恒 aria-live="off"，播报只发生在 live-region 里',-1)),o(a,{src:"thread/03-status"}),t[8]||(t[8]=e("h3",{id:"触底加载更多",tabindex:"-1"},[d("触底加载更多 "),e("a",{class:"header-anchor",href:"#触底加载更多","aria-label":'Permalink to "触底加载更多"'},"​")],-1)),t[9]||(t[9]=e("p",null,"stick-change 报到底，宿主据此去取下一页；先往上滚一段再滚回底部，取回来的消息追加在后面",-1)),o(a,{src:"thread/04-load-more"}),t[10]||(t[10]=e("h3",{id:"自己画回到底部的入口",tabindex:"-1"},[d("自己画回到底部的入口 "),e("a",{class:"header-anchor",href:"#自己画回到底部的入口","aria-label":'Permalink to "自己画回到底部的入口"'},"​")],-1)),t[11]||(t[11]=e("p",null,"在不在底、怎么滚回底部两件事外部都拿得到，不用内置那颗浮动按钮也能拼出一条自己的提示栏",-1)),o(a,{src:"thread/05-scroll-control"}),t[12]||(t[12]=e("h3",{id:"会话页",tabindex:"-1"},[d("会话页 "),e("a",{class:"header-anchor",href:"#会话页","aria-label":'Permalink to "会话页"'},"​")],-1)),t[13]||(t[13]=e("p",null,"线程管滚动与粘底，编辑器管收话：发出去先落一条自己的消息，回话一段段写进来时消息区自动跟到底",-1)),o(a,{src:"thread/06-chat"}),t[14]||(t[14]=e("h3",{id:"向上加载更早的消息",tabindex:"-1"},[d("向上加载更早的消息 "),e("a",{class:"header-anchor",href:"#向上加载更早的消息","aria-label":'Permalink to "向上加载更早的消息"'},"​")],-1)),t[15]||(t[15]=e("p",null,"视口的滚动事件直接监听：滚到接近顶部就去取上一页，取回来的插在最前面",-1)),o(a,{src:"thread/07-load-earlier"}),t[16]||(t[16]=e("h3",{id:"跳到指定的一条",tabindex:"-1"},[d("跳到指定的一条 "),e("a",{class:"header-anchor",href:"#跳到指定的一条","aria-label":'Permalink to "跳到指定的一条"'},"​")],-1)),t[17]||(t[17]=e("p",null,"视口节点与消息节点都在宿主手上：滚到顶、定位到某一条都是一次普通的 DOM 操作",-1)),o(a,{src:"thread/08-scroll-to"}),t[18]||(t[18]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-thread&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhThreadContent</code> <code>XhThreadLiveRegion</code> <code>XhThreadRoot</code> <code>XhThreadScrollButton</code> <code>XhThreadViewport</code></td></tr><tr><td>组合式函数</td><td><code>useThread</code></td></tr><tr><td>状态机</td><td><code>threadMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/thread.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;thread&quot;</code>：<strong><code>root</code></strong> · <strong><code>viewport</code></strong> · <strong><code>content</code></strong> · <code>scroll-button</code> · <code>live-region</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>status</code></td><td><code>ThreadStatus</code></td><td></td><td>这一轮的运行态，由宿主传入。</td></tr><tr><td><code>threshold</code></td><td><code>number</code></td><td></td><td>距底多少 px 视为在底，缺省用粘底原语的默认值。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;ThreadTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onStickChange</code></td><td><code>(details: ThreadStickChangeDetails) =&gt; void</code></td><td></td><td>粘底状态变化时通知宿主。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>stick-change</code></td><td><code>ThreadStickChangeDetails</code></td><td>粘底状态变化；detail 为 <code>{ atBottom: boolean, sticking: boolean }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhThreadRoot</code></td><td><code>default</code></td><td><code>ThreadRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>scroll-button</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>STICK.CHANGE</code> · <code>SCROLL_TO_BOTTOM</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useThread</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>status</code></td><td><code>ThreadStatus</code></td><td></td></tr><tr><td><code>atBottom</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>sticking</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>showScrollButton</code></td><td><code>boolean</code></td><td>是否显示回到底部按钮，不在底部时为 true。</td></tr><tr><td><code>scrollToBottom</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getScrollButtonProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getLiveRegionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/practices/structural-roles/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code></td><td>焦点进入消息区</td><td>消息区自身可聚焦，方向键/PageUp/PageDown 交给浏览器滚动，组件不接管</td></tr><tr><td><code>Space</code> / <code>Enter</code></td><td>焦点在&quot;回到底部&quot;按钮上</td><td>滚回底部并重新粘附</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>viewport</code></td><td><code>aria-label</code></td><td>label.log</td></tr><tr><td><code>viewport</code></td><td><code>aria-live</code></td><td>&#39;off&#39;</td></tr><tr><td><code>viewport</code></td><td><code>role</code></td><td>&#39;log&#39;</td></tr><tr><td><code>scroll-button</code></td><td><code>aria-label</code></td><td>label.scrollToBottom</td></tr><tr><td><code>live-region</code></td><td><code>aria-atomic</code></td><td>&#39;true&#39;</td></tr><tr><td><code>live-region</code></td><td><code>aria-live</code></td><td>&#39;polite&#39;</td></tr><tr><td><code>live-region</code></td><td><code>role</code></td><td>&#39;status&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/thread.css</code> 按部件选择：<code>[data-scope=&quot;thread&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-status</code></td><td>props.status</td></tr><tr><td><code>viewport</code></td><td><code>data-status</code></td><td>props.status</td></tr><tr><td><code>scroll-button</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-thread-content-gap</code> · <code>--xh-thread-content-py</code> · <code>--xh-thread-scroll-button-bg</code> · <code>--xh-thread-scroll-button-bg-active</code> · <code>--xh-thread-scroll-button-bg-hover</code> · <code>--xh-thread-scroll-button-border</code> · <code>--xh-thread-scroll-button-fg</code> · <code>--xh-thread-scroll-button-font-size</code> · <code>--xh-thread-scroll-button-font-weight</code> · <code>--xh-thread-scroll-button-gap</code> · <code>--xh-thread-scroll-button-h</code> · <code>--xh-thread-scroll-button-inset</code> · <code>--xh-thread-scroll-button-px</code> · <code>--xh-thread-scroll-button-radius</code> · <code>--xh-thread-scroll-button-shadow</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>下面接<a href="./composer">消息编辑器</a>；消息里放<a href="./code-block">代码块</a>与 <code>@xihan-ui/markdown</code>。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>用户往上翻时绝不要强行拉回底部。</li><li>向上加载更早消息后要补偿滚动位置，否则视野会突然跳走。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>流式生成时每个增量都播报给读屏：用户什么也听不清。</li><li>新消息到达时无条件滚到底，哪怕用户正在上面读。</li></ul>',47))])}const k=h(s,[["render",u]]);export{P as __pageData,k as default};
